values ('7e570000-0000-4000-8000-000000000014', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'seared-scallops-beurre-blanc-pea-puree', 'seared-scallops-beurre-blanc-pea-puree', 'Seared Scallops, Beurre Blanc, Pea Purée & Crispy Shallots', 'Deeply caramelised scallops on vivid pea purée with a classic beurre blanc and crisp shallot rings — a chef''s-table plate.', 'french', 5, 40, 30, 70, 2, 'main', null, 0, array['stove', 'blender']::text[], array['date-night', 'composed-plate', 'technique']::text[], array['Buy dry-packed scallops; wet-packed ones release water and won''t brown.', 'Beurre blanc is an emulsion: keep it warm, never hot. Above roughly 135°F it can break.', 'If the beurre blanc breaks, whisk a spoonful of cream in a clean pan and slowly whisk the broken sauce into it.', 'USDA guidance for scallops is 145°F, or until the flesh is opaque and firm.']::text[], 'https://images.unsplash.com/photo-1732321501974-1ec272b68ecf', 'Seared scallops in sauce', 'Meg von Haartman', 'https://unsplash.com/@traveleroohlala', 'https://unsplash.com/photos/a-green-plate-topped-with-scallops-covered-in-sauce-Wf9aOQoBJ7g', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'date_night']::text[], array['stew', 'pan_fry']::text[], array['tangy', 'rich', 'fresh']::text[], '{}'::text[], null, null, 'seared-scallops-beurre-blanc-pea-puree-and-crispy-shallots', 'classic', null, null, 'owned', array['milk', 'shellfish']::text[], array['shellfish']::text[], array['pescatarian', 'gluten_free']::text[], array['frozen pea', 'shallot', 'white wine', 'wine vinegar', 'heavy cream', 'lemon juice', 'dry-packed scallop']::text[], 'dry-packed scallop|frozen pea|heavy cream|lemon juice|shallot|white wine|wine vinegar',
  null, null, null, null, null, null, null, null)
