values ('7e570000-0000-4000-8000-000000000023', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'vanilla-cream-puffs', 'vanilla-cream-puffs', 'Vanilla Cream Puffs', 'Crisp, hollow choux puffs filled with silky vanilla pastry cream and a dusting of sugar.', 'french', 4, 45, 40, 205, 8, 'dessert', 'pastries', 120, array['stove', 'oven']::text[], array['dinner-party', 'technique']::text[], array['Don''t open the oven for the first 20 minutes — the steam inside is what puffs the choux.', 'Make the pastry cream the day before; fill the puffs no more than a few hours before serving.']::text[], 'https://images.unsplash.com/photo-1786918467116-045c0f772b1f', 'A group of golden brown cream puffs arranged on parchment paper', 'Culinarissimo', 'https://unsplash.com/@culinarissimo', 'https://unsplash.com/photos/cream-puffs-on-parchment-paper--20DSoQreM4', 'unsplash', true, 'public', false,
