values ('7e570000-0000-4000-8000-000000000024', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'raspberry-mousse-entremets', 'raspberry-mousse-entremets', 'Raspberry Mousse Entremets with Mirror Glaze', 'Individual layered cakes: a crisp chocolate base, airy raspberry mousse and a glossy white-chocolate mirror glaze.', 'french', 5, 90, 20, 830, 6, 'dessert', 'plated', 720, array['stove', 'oven', 'stand_mixer', 'blender']::text[], array['dinner-party', 'technique', 'make-ahead']::text[], array['Use a thermometer: the glaze pours best at 90–95°F. Hotter and it slides off; cooler and it goes lumpy.', 'The mousse must be frozen solid before glazing, so start the day before.']::text[], 'https://images.unsplash.com/photo-1761637604698-0f9e9d3278ee', 'A small pink mousse cake topped with a raspberry and red glaze', 'Christian Agbede', 'https://unsplash.com/@chriscreations__', 'https://unsplash.com/photos/a-small-pink-cake-topped-with-raspberry-and-red-glaze--wOczGwXJOk', 'unsplash', true, 'public', false,
