insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7e570000-0000-4000-8000-000000000024', 1, 'Chocolate base', 'Pulse the flour, cocoa, sugar and butter until sandy, add the yolk and press into a disc. Chill 30 minutes.', 1800, null, null),
  ('7e570000-0000-4000-8000-000000000024', 2, 'Chocolate base', 'Roll ⅛ inch thick, cut six 3-inch rounds and bake at 350°F until firm, 12–14 minutes. Cool.', 780, 176.7, null),
  ('7e570000-0000-4000-8000-000000000024', 3, 'Raspberry mousse', 'Blend the raspberries with the sugar and press through a sieve to remove the seeds. You need about 1 cup purée.', null, null, null),
  ('7e570000-0000-4000-8000-000000000024', 4, 'Raspberry mousse', 'Sprinkle the gelatin over the cold water for 5 minutes, then melt it gently and whisk into a third of the purée; whisk back into the rest.', null, null, null),
  ('7e570000-0000-4000-8000-000000000024', 5, 'Raspberry mousse', 'Whip the cream to soft peaks and fold it into the purée once it''s cool but not set.', null, null, null),
  ('7e570000-0000-4000-8000-000000000024', 6, 'Raspberry mousse', 'Line six 3-inch rings or silicone moulds, fill with mousse, top with a base round, and freeze solid, at least 8 hours.', 28800, null, null),
  ('7e570000-0000-4000-8000-000000000024', 7, 'Mirror glaze', 'Bloom the gelatin in the cold water. Bring the sugar, corn syrup and water to a boil, then take off the heat.', null, null, null),
  ('7e570000-0000-4000-8000-000000000024', 8, 'Mirror glaze', 'Stir in the gelatin and condensed milk, pour over the white chocolate and blend without lifting the blender (no bubbles). Tint if you like.', null, null, null),
  ('7e570000-0000-4000-8000-000000000024', 9, 'Mirror glaze', 'Strain and cool to 90–95°F.', null, null, null),
  ('7e570000-0000-4000-8000-000000000024', 10, 'Mirror glaze', 'Unmould the frozen cakes onto a rack over a tray and pour the glaze over in one confident motion. Trim the drips and thaw in the fridge at least 4 hours before serving.', 14400, null, null);

