insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('28f23103-abb7-4389-8e3f-99741926815a', 1, 'Sauce', '3 tbsp tamarind concentrate', 'tamarind concentrate', 3, 'tbsp', null, false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 2, 'Sauce', '3 tbsp fish sauce', 'fish sauce', 3, 'tbsp', null, false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 3, 'Sauce', '3 tbsp palm sugar, or light brown sugar', 'palm sugar', 3, 'tbsp', 'or light brown sugar', false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 4, 'Noodles', '8 oz dried flat rice noodles, about ¼ inch wide', 'dried flat rice noodles', 8, 'oz', 'about ¼ inch wide', false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 5, 'Noodles', '3 tbsp vegetable oil', 'vegetable oil', 3, 'tbsp', null, false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 6, 'Noodles', '12 oz large shrimp, peeled and deveined', 'large shrimp', 12, 'oz', 'peeled and deveined', false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 7, 'Noodles', '4 oz firm tofu, diced small', 'firm tofu', 4, 'oz', 'diced small', false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 8, 'Noodles', '2 cloves garlic, minced', 'garlic', 2, 'clove', 'minced', false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 9, 'Noodles', '1 shallot, thinly sliced', 'shallot', 1, null, 'thinly sliced', false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 10, 'Noodles', '2 eggs', 'eggs', 2, null, null, false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 11, 'Noodles', '2 cups bean sprouts', 'bean sprouts', 2, 'cup', null, false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 12, 'Noodles', '4 scallions, cut into 1-inch lengths', 'scallions', 4, null, 'cut into 1-inch lengths', false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 13, 'To serve', '⅓ cup roasted peanuts, chopped', 'roasted peanuts', 0.33, 'cup', 'chopped', false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 14, 'To serve', '1 lime, cut into wedges', 'lime', 1, null, 'cut into wedges', false),
  ('28f23103-abb7-4389-8e3f-99741926815a', 15, 'To serve', '1 tsp dried chili flakes', 'dried chili flakes', 1, 'tsp', null, true);
delete from public.recipe_instructions where recipe_id = '28f23103-abb7-4389-8e3f-99741926815a';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('28f23103-abb7-4389-8e3f-99741926815a', 1, 'Noodles', 'Soak the noodles in warm (not hot) water until bendy but still firm, 20–30 minutes. Drain well.', 1500, null, null),
  ('28f23103-abb7-4389-8e3f-99741926815a', 2, 'Sauce', 'Warm the tamarind, fish sauce and sugar in a small pan until the sugar dissolves. Taste: it should be sour, salty and sweet in balance.', null, null, null),
  ('28f23103-abb7-4389-8e3f-99741926815a', 3, 'Noodles', 'Heat half the oil in a wok over high heat. Cook the shrimp until pink and opaque, about 2 minutes, then set aside.', 120, null, 62.8),
  ('28f23103-abb7-4389-8e3f-99741926815a', 4, 'Noodles', 'Add the rest of the oil, then the tofu, garlic and shallot; stir-fry 1 minute. Push to one side, crack in the eggs and scramble until just set.', 120, null, null),
  ('28f23103-abb7-4389-8e3f-99741926815a', 5, 'Noodles', 'Add the noodles and sauce and toss constantly until the noodles are soft and glossy, 2–3 minutes; add a splash of water if they stick.', 180, null, null),
  ('28f23103-abb7-4389-8e3f-99741926815a', 6, 'Noodles', 'Toss in the shrimp, bean sprouts and scallions for 30 seconds. Serve with peanuts, lime and chili.', null, null, null);

