  ('7b980d7b-6d3a-4835-90a8-ebbd5e533fd8', 2, 'Oysters', 'Discard any oysters that are open or cracked. Holding each in a folded towel, work an oyster knife into the hinge, twist to pop it, then slide the blade under the top shell to cut the muscle.', null, null, null),
  ('7b980d7b-6d3a-4835-90a8-ebbd5e533fd8', 3, 'Oysters', 'Loosen the oyster from the bottom shell, keeping its liquor, and set on crushed ice.', null, null, null),
